const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const sourcePath = path.join(root, 'src', 'SipWebPhoneProviders.json');
const targetPath = path.join(root, 'src', 'SipWebPhoneProviders.js');
const table = JSON.parse(fs.readFileSync(sourcePath, 'utf8'));
const output = [
  '// Generated from SipWebPhoneProviders.json. Do not edit this file directly.',
  '(function (root) {',
  `  root.FritzSipProviderTable = ${JSON.stringify(table, null, 2).replace(/\n/g, '\n  ')};`,
  '})(typeof globalThis !== "undefined" ? globalThis : this);',
  ''
].join('\n');

fs.writeFileSync(targetPath, output, 'utf8');
